argv:
system('ruby', '/Users/dinko/.claude/skills/agentx/scripts/check_workflow_yaml.rb', '.github/workflows/fork-release.yml') or abort('yaml')
f = '.github/workflows/fork-release.yml'
w = YAML.load_file(f)
s = File.read(f)
on = w[true] || w['on']
abort 'tags' unless on['push']['tags'] == ['fork-*']
abort 'dispatch' unless on['workflow_dispatch']['inputs']['tag']['required'] == true
jobs = w['jobs']
dist = jobs.values.find { |j| j.dig('strategy', 'matrix', 'include') }
entries = dist['strategy']['matrix']['include']
names = entries.map { |e| e['name'] }
abort "platforms #{names}" unless names.sort == %w[linux-arm64 linux-x86_64 macos-arm64 windows-arm64 windows-x86_64]
optional = entries.select { |e| e['optional'] == true }.map { |e| e['name'] }
abort "optional #{optional}" unless optional == ['windows-arm64']
abort 'continue-on-error' unless dist['continue-on-error'] == '${{ matrix.optional == true }}'
no_android = entries.select { |e| e['android'] == 'none' }.map { |e| e['name'] }
abort "android #{no_android}" unless no_android == ['linux-arm64']
abort 'android steps' unless dist['steps'].any? { |st| st['if'] == "matrix.android == 'none'" && st['run'].to_s.include?('let android = false;') }
required = entries.reject { |e| e['optional'] }.map { |e| "nsh-#{e['name']}" + (e['name'].start_with?('windows') ? '.zip' : '.tar.gz') }
release = jobs['release']
abort 'needs' unless release['needs'] == 'dist' && release['if'].to_s.include?('!cancelled()')
check = release['steps'].find { |st| st['name'] == 'Check the archives' }
listed = check['run'][/for archive in ([^;]+);/, 1].split
abort "archives #{listed} != #{required}" unless listed.sort == required.sort
gh = release['steps'].find { |st| st['uses'].to_s.start_with?('softprops/action-gh-release@') }
abort 'draft' unless gh['with']['draft'] == false && gh['with']['generate_release_notes'] == true && gh['with']['name'] == '${{ env.TAG }}'
abort 'attest' unless release['steps'].any? { |st| st['uses'].to_s.start_with?('actions/attest-build-provenance@') }
abort 'installers' if s =~ /install\.sh|install\.ps1|envsubst|homebrew|scoop|cargo publish/i
puts 'fork-release.yml ok'
